/* From Uiverse.io by Cornerstone-04 - Tags: loader */
.__UIV_SCOPE__ .loader {
  width: 100%;
  height: 100%;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 10px;
  transition: 0.5s linear;
}

.__UIV_SCOPE__ .ball {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  animation: bounce6135 1s alternate infinite;
  transition: 0.5s linear;
}

.__UIV_SCOPE__ .ball {
  background: #fff;
}

.__UIV_SCOPE__ .ball:nth-child(2) {
  animation-delay: 0.25s;
}

.__UIV_SCOPE__ .ball:nth-child(3) {
  animation-delay: 0.5s;
}

@keyframes bounce6135 {
  from {
    transform: scale(2);
  }

  to {
    transform: scale(1);
  }
}
